-- 0002_identity_by_default.sql
--
-- GENERATED ALWAYS AS IDENTITY rejects explicit id values, which the SQLite
-- data migration requires (it preserves the original row ids so conversation
-- ordering and foreign keys stay intact).
--
-- GENERATED BY DEFAULT keeps auto-generation for normal inserts while still
-- allowing an explicit id, which is what a restore/seeding workflow needs.

ALTER TABLE diet_profiles   ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE meal_schedules  ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE food_logs       ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE conversations   ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE user_activities ALTER COLUMN id SET GENERATED BY DEFAULT;
